// src/check.js: is anything listening on host:port? One TCP connect with a timeout, nothing more.
import net from 'node:net';
import { isLanAddress } from './validate.js';

export function checkPort(host, port, timeoutMs = 1500) {
  return new Promise((resolve) => {
    const started = performance.now();
    const socket = net.connect({ host, port });
    const finish = (state, error = null) => {
      socket.destroy(); // close at once: we only wanted to know if the handshake completes
      resolve({ state, ms: Math.round(performance.now() - started), error });
    };
    socket.setTimeout(timeoutMs);
    socket.once('connect', () => finish('up'));
    socket.once('timeout', () => finish('down', 'ETIMEDOUT'));
    socket.once('error', (err) => finish('down', err.code ?? err.message));
  });
}

// Safety rule from the Python capstone: only probe your own LAN and this machine.
export async function checkDevice(device, timeoutMs) {
  if (!isLanAddress(device.ip)) return { state: 'skipped', ms: 0, error: 'not a LAN address' };
  return checkPort(device.ip, device.port, timeoutMs);
}

