// src/monitor.js: check every device on a timer, keep the latest result, announce changes
import { EventEmitter } from 'node:events';
import { checkDevice } from './check.js';

const NEVER = Object.freeze({ state: 'unknown', ms: null, error: null, checkedAt: null });

export class Monitor extends EventEmitter {
  #store;
  #timeoutMs;
  #results = new Map();
  #timer = null;
  #running = false;
  lastSweep = null;

  constructor(store, { timeoutMs = 1500 } = {}) {
    super();
    this.#store = store;
    this.#timeoutMs = timeoutMs;
  }

  result(id) {
    return this.#results.get(id) ?? NEVER;
  }

  forget(id) {
    this.#results.delete(id);
  }

  async check(device) {
    const result = { ...(await checkDevice(device, this.#timeoutMs)), checkedAt: new Date().toISOString() };
    const before = this.result(device.id).state;
    this.#results.set(device.id, result);
    const firstUp = before === 'unknown' && result.state === 'up'; // a quiet start: only report problems
    if (before !== result.state && result.state !== 'skipped' && !firstUp) {
      this.emit('change', { device, from: before, to: result.state, result });
    }
    return result;
  }

  async sweep() {
    await Promise.all(this.#store.list().map((d) => this.check(d)));
    this.lastSweep = new Date().toISOString();
  }

  start(everyMs) {
    if (everyMs <= 0 || this.#running) return;
    this.#running = true;
    const loop = async () => {
      try {
        await this.sweep();
      } catch (err) {
        console.error('sweep failed:', err);
      }
      if (this.#running) this.#timer = setTimeout(loop, everyMs); // next sweep after this one ends
    };
    loop();
  }

  stop() {
    this.#running = false;
    clearTimeout(this.#timer);
  }
}

// src/app.js: the Express application: API routes, feeds, static files, errors
import express from 'express';
import http from 'node:http';
import path from 'node:path';
import { openStore } from './store.js';
import { validateDevice } from './validate.js';
import { Monitor } from './monitor.js';
import { devicesToXml, eventsToRss } from './feeds.js';

const PUBLIC = path.join(import.meta.dirname, '..', 'public');

export async function createApp({ dataFile, timeoutMs = 1500, log = console.log } = {}) {
  const store = await openStore(dataFile);
  const monitor = new Monitor(store, { timeoutMs });
  const events = []; // newest first, at most 50
  let lastEvent = 0;

  function record(kind, device, text) {
    events.unshift({ id: ++lastEvent, time: new Date().toISOString(), kind, deviceId: device.id, text });
    events.length = Math.min(events.length, 50);
  }
  monitor.on('change', ({ device, to, result }) => {
    record(to, device, `${device.name} (${device.ip}:${device.port}) is ${to}${result.error ? ` (${result.error})` : ''}`);
  });

  const withStatus = (d) => ({ ...d, status: monitor.result(d.id) });
  const notFound = (res, id) => res.status(404).json({ error: `device ${id} not found` });

  function parseBody(req, res, exceptId = null) {
    if (!req.is('application/json')) {
      res.status(415).json({ error: 'send JSON with Content-Type: application/json' });
      return null;
    }
    const { device, errors } = validateDevice(req.body);
    if (errors) {
      res.status(422).json({ error: 'validation failed', fields: errors });
      return null;
    }
    if (store.nameTaken(device.name, exceptId)) {
      res.status(409).json({ error: `a device named ${device.name} already exists`, fields: { name: 'this name is taken' } });
      return null;
    }
    return device;
  }

  const app = express();
  app.disable('x-powered-by');
  app.use((req, res, next) => {
    const t0 = performance.now();
    res.on('finish', () => log(`${req.method} ${req.originalUrl} ${res.statusCode} ${Math.round(performance.now() - t0)}ms`));
    next();
  });
  app.use(express.static(PUBLIC));
  app.use(express.json({ limit: '10kb' }));

  const api = express.Router();

  api.get('/devices', (req, res) => {
    const { type, state, q } = req.query;
    let list = store.list().map(withStatus);
    if (type) list = list.filter((d) => d.type === type);
    if (state) list = list.filter((d) => d.status.state === state);
    if (q) {
      const needle = String(q).toLowerCase();
      list = list.filter((d) => d.name.toLowerCase().includes(needle) || d.ip.includes(needle));
    }
    res.set('X-Total-Count', String(list.length)).json(list);
  });

  api.get('/devices.xml', (req, res) => {
    res.type('application/xml').send(devicesToXml(store.list(), (id) => monitor.result(id)));
  });

  api.get('/devices/:id', (req, res) => {
    const device = store.get(Number(req.params.id));
    if (!device) return notFound(res, req.params.id);
    res.json(withStatus(device));
  });

  api.post('/devices', async (req, res) => {
    const fields = parseBody(req, res);
    if (!fields) return;
    const device = await store.add(fields);
    record('added', device, `${device.name} (${device.ip}) was added`);
    monitor.check(device).catch(console.error); // first check now; the client sees it on its next poll
    res.status(201).location(`/api/devices/${device.id}`).json(withStatus(device));
  });

  api.put('/devices/:id', async (req, res) => {
    const id = Number(req.params.id);
    if (!store.get(id)) return notFound(res, req.params.id);
    const fields = parseBody(req, res, id);
    if (!fields) return;
    const device = await store.update(id, fields);
    monitor.forget(id);
    record('updated', device, `${device.name} (${device.ip}:${device.port}) was updated`);
    monitor.check(device).catch(console.error);
    res.json(withStatus(device));
  });

  api.delete('/devices/:id', async (req, res) => {
    const device = await store.remove(Number(req.params.id));
    if (!device) return notFound(res, req.params.id);
    monitor.forget(device.id);
    record('removed', device, `${device.name} (${device.ip}) was removed`);
    res.status(204).end();
  });

  api.post('/devices/:id/check', async (req, res) => {
    const device = store.get(Number(req.params.id));
    if (!device) return notFound(res, req.params.id);
    const result = await monitor.check(device);
    if (result.state === 'skipped') return res.status(403).json({ error: `refusing to probe ${device.ip}: not a LAN address` });
    res.json({ id: device.id, ip: device.ip, port: device.port, ...result });
  });

  api.get('/status', (req, res) => {
    const devices = store.list().map((d) => ({ id: d.id, ...monitor.result(d.id) }));
    const count = (s) => devices.filter((d) => d.state === s).length;
    res.json({
      time: new Date().toISOString(),
      lastSweep: monitor.lastSweep,
      version: store.version,
      lastEvent,
      total: devices.length,
      up: count('up'),
      down: count('down'),
      unknown: count('unknown'),
      devices,
    });
  });

  api.get('/events', (req, res) => res.json(events));

  app.use('/api', api);
  app.get('/feed.rss', (req, res) => {
    res.type('application/rss+xml').send(eventsToRss(events, `${req.protocol}://${req.get('host')}`));
  });
  app.use('/api', (req, res) => res.status(404).json({ error: `no route for ${req.method} ${req.originalUrl}` }));

  app.use((err, req, res, next) => {
    if (err.type === 'entity.parse.failed') return res.status(400).json({ error: 'body must be valid JSON' });
    if (err.type === 'entity.too.large') return res.status(413).json({ error: 'body too large (10 kB max)' });
    console.error(err);
    res.status(500).json({ error: 'internal server error' });
  });

  return { app, server: http.createServer(app), store, monitor, events }; // the caller starts monitor and server
}

