// server.js: read the configuration, build the app, listen, shut down cleanly
import path from 'node:path';

try {
  process.loadEnvFile(); // ./.env, if there is one (Node 20.12+); real environment variables win
} catch (err) {
  if (err.code !== 'ENOENT') throw err;
}

const PORT = Number(process.env.PORT ?? 3000);
const HOST = process.env.HOST ?? '127.0.0.1'; // this Mac only, until you decide otherwise
const DATA_FILE = process.env.DATA_FILE ?? path.join(import.meta.dirname, 'data', 'devices.json');
const CHECK_EVERY = Number(process.env.CHECK_EVERY ?? 30); // seconds between sweeps; 0 turns them off

const impl = process.env.APP === 'http' ? './src/http-app.js' : './src/app.js'; // APP=http: no Express
const { createApp } = await import(impl);
const { server, monitor } = await createApp({ dataFile: DATA_FILE });

server.on('error', (err) => {
  console.error(err.code === 'EADDRINUSE' ? `port ${PORT} is in use (lsof -nP -iTCP:${PORT} -sTCP:LISTEN)` : err.message);
  process.exit(1);
});
server.listen(PORT, HOST, () => {
  console.log(`dashboard on http://${HOST}:${PORT}  data: ${path.relative(process.cwd(), DATA_FILE)}  sweep: ${CHECK_EVERY}s`);
  monitor.start(CHECK_EVERY * 1000); // after listen, so the first sweep can reach this server too
});

function shutdown(signal) {
  console.log(`${signal} received, closing`);
  monitor.stop();
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 2000).unref(); // do not wait forever for idle keep-alive sockets
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

