// test/api.test.js: start the whole app on a free port with a throwaway data file, then use it like a client
import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { once } from 'node:events';
import { tmpdir } from 'node:os';
import net from 'node:net';
import path from 'node:path';

const impl = process.env.APP === 'http' ? '../src/http-app.js' : '../src/app.js';
const { createApp } = await import(impl);

let ctx, base, dir, dataFile, listener, openPort;

async function freePort() { // ask the OS for a port, then release it: nothing listens there afterwards
  const s = net.createServer().listen(0, '127.0.0.1');
  await once(s, 'listening');
  const { port } = s.address();
  s.close();
  return port;
}

before(async () => {
  listener = net.createServer((socket) => socket.end()); // a service for the checker to find
  listener.listen(0, '127.0.0.1');
  await once(listener, 'listening');
  openPort = listener.address().port;

  dir = await mkdtemp(path.join(tmpdir(), 'dashboard-test-'));
  dataFile = path.join(dir, 'devices.json');
  await writeFile(dataFile, JSON.stringify({
    nextId: 3,
    devices: [
      { id: 1, name: 'listener', ip: '127.0.0.1', port: openPort, type: 'server', notes: '' },
      { id: 2, name: 'router', ip: '192.168.1.1', port: 80, type: 'router', notes: 'R&D <lab>' },
    ],
  }));
  ctx = await createApp({ dataFile, timeoutMs: 300, log: () => {} }); // no sweeps: tests call checks explicitly
  ctx.server.listen(0, '127.0.0.1');
  await once(ctx.server, 'listening');
  base = `http://127.0.0.1:${ctx.server.address().port}`;
});

after(async () => {
  ctx.monitor.stop();
  ctx.server.close();
  listener.close();
  await rm(dir, { recursive: true, force: true });
});

const get = (p) => fetch(base + p);
const send = (method, p, body) =>
  fetch(base + p, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });

describe('reading devices', () => {
  it('lists every device with a status and a count header', async () => {
    const res = await get('/api/devices');
    assert.equal(res.status, 200);
    assert.equal(res.headers.get('x-total-count'), '2');
    const list = await res.json();
    assert.deepEqual(list.map((d) => d.name), ['listener', 'router']);
    assert.equal(list[0].status.state, 'unknown');
  });

  it('filters by type and searches name or ip', async () => {
    const names = async (q) => (await (await get(`/api/devices?${q}`)).json()).map((d) => d.name);
    assert.deepEqual(await names('type=router'), ['router']);
    assert.deepEqual(await names('q=LIST'), ['listener']);
    assert.deepEqual(await names('q=192.168'), ['router']);
  });

  it('answers 404 in JSON for an unknown id or route', async () => {
    const res = await get('/api/devices/99');
    assert.equal(res.status, 404);
    assert.deepEqual(await res.json(), { error: 'device 99 not found' });
    assert.equal((await get('/api/nothing')).status, 404);
  });
});

describe('changing devices', () => {
  it('creates a device: 201, Location, saved to the file', async () => {
    const res = await send('POST', '/api/devices', { name: 'pi', ip: '127.0.0.1', port: openPort, type: 'server' });
    assert.equal(res.status, 201);
    const pi = await res.json();
    assert.equal(res.headers.get('location'), `/api/devices/${pi.id}`);
    const saved = JSON.parse(await readFile(dataFile, 'utf8'));
    assert.equal(saved.nextId, pi.id + 1);
    assert.ok(saved.devices.some((d) => d.name === 'pi'));
  });

  it('rejects bad fields with 422 and one message per field', async () => {
    const res = await send('POST', '/api/devices', { name: '', ip: '8.8.8.8', port: 70000 });
    assert.equal(res.status, 422);
    const body = await res.json();
    assert.deepEqual(Object.keys(body.fields).sort(), ['ip', 'name', 'port']);
    assert.match(body.fields.ip, /LAN/);
  });

  it('rejects a duplicate name (409), broken JSON (400) and form bodies (415)', async () => {
    assert.equal((await send('POST', '/api/devices', { name: 'Router', ip: '192.168.1.2' })).status, 409);
    const broken = await fetch(`${base}/api/devices`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{"name":' });
    assert.equal(broken.status, 400);
    const form = await fetch(`${base}/api/devices`, { method: 'POST', body: new URLSearchParams({ name: 'x', ip: '10.0.0.9' }) });
    assert.equal(form.status, 415);
  });

  it('replaces with PUT, deletes with DELETE', async () => {
    const put = await send('PUT', '/api/devices/2', { name: 'router', ip: '192.168.1.254', port: 443, type: 'router', notes: 'R&D <lab>' });
    assert.equal(put.status, 200);
