    assert.equal((await fetch(`${base}/api/devices/${created.id}`, { method: 'DELETE' })).status, 204);
    assert.equal((await get(`/api/devices/${created.id}`)).status, 404);
    assert.equal((await send('PUT', `/api/devices/${created.id}`, { name: 'temp', ip: '10.0.0.9' })).status, 404);
  });
