describe('checks, status and feeds', () => {
  it('reports up for a listening port and down for a closed one', async () => {
    const up = await (await fetch(`${base}/api/devices/1/check`, { method: 'POST' })).json();
    assert.equal(up.state, 'up');
    const closed = await (await send('POST', '/api/devices', { name: 'closed', ip: '127.0.0.1', port: await freePort() })).json();
    const down = await (await fetch(`${base}/api/devices/${closed.id}/check`, { method: 'POST' })).json();
    assert.equal(down.state, 'down');
    assert.equal(down.error, 'ECONNREFUSED');
  });

  it('summarises states and exposes a data version', async () => {
