// public/api.js: every request to the server goes through request(): one place for errors and timeouts
export class ApiError extends Error {
  constructor(message, status = 0, fields = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status; // 0 means the server never answered
    this.fields = fields; // per-field messages from a 422 or 409
  }
}

async function request(path, { method = 'GET', body, timeoutMs = 5000 } = {}) {
  let res;
  try {
    res = await fetch(path, {
      method,
      headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: AbortSignal.timeout(timeoutMs),
    });
  } catch (err) {
    throw new ApiError(err.name === 'TimeoutError' ? `no answer within ${timeoutMs / 1000} s` : 'cannot reach the server');
  }
  if (res.status === 204) return null;
  const isJson = (res.headers.get('content-type') ?? '').includes('application/json');
  const data = isJson ? await res.json() : await res.text();
  if (!res.ok) throw new ApiError(data?.error ?? `${res.status} ${res.statusText}`, res.status, data?.fields ?? {});
  return data;
}

const query = (filters) => new URLSearchParams(Object.entries(filters).filter(([, v]) => v !== '')).toString();

export const api = {
  list: (filters = {}) => request(`/api/devices?${query(filters)}`),
  create: (device) => request('/api/devices', { method: 'POST', body: device }),
  update: (id, device) => request(`/api/devices/${id}`, { method: 'PUT', body: device }),
  remove: (id) => request(`/api/devices/${id}`, { method: 'DELETE' }),
  check: (id) => request(`/api/devices/${id}/check`, { method: 'POST', timeoutMs: 10000 }),
  status: () => request('/api/status'),
  events: () => request('/api/events'),
};

// public/render.js: data in, DOM out. Text always goes in with textContent, never innerHTML.
const template = document.querySelector('#card-template');

function describe(status) {
  if (!status?.checkedAt) return 'not checked yet';
  const at = new Date(status.checkedAt).toLocaleTimeString();
  return status.state === 'up' ? `answered in ${status.ms} ms at ${at}` : `${status.error ?? 'no answer'} at ${at}`;
}

export function setState(card, status) {
  const state = status?.state ?? 'unknown';
  card.dataset.state = state; // CSS colours the card from this attribute
  card.querySelector('.badge').textContent = state;
  card.querySelector('.detail').textContent = describe(status);
}

function makeCard(device) {
  const card = template.content.firstElementChild.cloneNode(true);
  card.dataset.id = device.id;
  card.querySelector('.name').textContent = device.name;
  card.querySelector('.ip').textContent = device.ip;
  card.querySelector('.port').textContent = device.port;
  card.querySelector('.type').textContent = device.type;
  card.querySelector('.notes').textContent = device.notes;
  setState(card, device.status);
  return card;
}

export function renderDevices(list, devices) {
  list.replaceChildren(...devices.map(makeCard)); // one DOM update for the whole list
}

export function updateStates(list, statuses) {
  const byId = new Map(statuses.map((s) => [s.id, s]));
  for (const card of list.children) {
    const status = byId.get(Number(card.dataset.id)); // dataset values are strings, ids are numbers
    if (status) setState(card, status);
  }
}

export function renderSummary(el, s) {
  el.textContent = `${s.total} devices: ${s.up} up, ${s.down} down, ${s.unknown} unknown`;
}

export function renderEvents(ol, events) {
  ol.replaceChildren(...events.slice(0, 8).map((e) => {
    const li = document.createElement('li');
    const time = document.createElement('time');
    time.dateTime = e.time;
    time.textContent = new Date(e.time).toLocaleTimeString();
    li.dataset.kind = e.kind;
    li.append(time, ' ', e.text);
    return li;
  }));
}

export function showErrors(form, fields = {}, message = '') {
  for (const p of form.querySelectorAll('.error')) p.textContent = '';
  for (const el of form.querySelectorAll('[aria-invalid]')) el.removeAttribute('aria-invalid');
  for (const [name, text] of Object.entries(fields)) {
    const p = form.querySelector(`#err-${name}`);
    if (p) p.textContent = text;
    form.elements[name]?.setAttribute('aria-invalid', 'true');
  }
  form.querySelector('#err-form').textContent = message;
}

// public/app.js: state, event listeners and polling. api.js talks, render.js draws.
import { api, ApiError } from './api.js';
import { renderDevices, updateStates, renderSummary, renderEvents, setState, showErrors } from './render.js';

const POLL_MS = 10_000;
const $ = (selector) => document.querySelector(selector);
const list = $('#list');
const form = $('#device-form');
const filters = $('#filters');
const state = { devices: [], version: null, lastEvent: null, timer: null };

function setBanner(text) {
  $('#banner').textContent = text;
  $('#banner').hidden = !text;
}

// ---------- loading and polling
async function loadList() {
  const wanted = Object.fromEntries(new FormData(filters));
  state.devices = await api.list(wanted);
  renderDevices(list, state.devices);
  $('#empty').hidden = state.devices.length > 0;
}

async function poll() {
  clearTimeout(state.timer);
  try {
    const status = await api.status();
    if (status.version !== state.version) { // devices changed since our last full load
      await loadList();
      state.version = status.version;
    } else {
      updateStates(list, status.devices); // same devices: just repaint the badges
    }
    if (status.lastEvent !== state.lastEvent) {
      renderEvents($('#events'), await api.events());
      state.lastEvent = status.lastEvent;
    }
    renderSummary($('#summary'), status);
    const now = new Date();
    $('#updated').dateTime = now.toISOString();
    $('#updated').textContent = now.toLocaleTimeString();
    setBanner('');
  } catch (err) {
    setBanner(`Server unreachable: ${err.message}. Showing the last data, retrying every ${POLL_MS / 1000} s.`);
  } finally {
    if (!document.hidden) state.timer = setTimeout(poll, POLL_MS);
  }
}

document.addEventListener('visibilitychange', () => { // no polling in a background tab
  if (document.hidden) clearTimeout(state.timer);
  else poll();
});

// ---------- filters: debounce typing so one request goes out after a 300 ms pause
function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), ms);
  };
}
filters.addEventListener('input', debounce(() => loadList().catch((err) => setBanner(err.message)), 300));
filters.addEventListener('submit', (event) => event.preventDefault());

// ---------- card buttons: one delegated listener for every card, present and future
list.addEventListener('click', async (event) => {
  const button = event.target.closest('button[data-action]');
  if (!button) return;
  const card = button.closest('.card');
  const id = Number(card.dataset.id);
  const device = state.devices.find((d) => d.id === id);
  try {
    if (button.dataset.action === 'edit') return startEdit(device);
    if (button.dataset.action === 'delete') {
      if (!confirm(`Delete ${device.name} (${device.ip})?`)) return;
      await api.remove(id);
      await poll();
    }
    if (button.dataset.action === 'check') {
      button.disabled = true;
      setState(card, await api.check(id));
    }
  } catch (err) {
    setBanner(err.message);
  } finally {
    button.disabled = false;
  }
});

// ---------- add and edit
function startEdit(device) {
  for (const name of ['id', 'name', 'ip', 'port', 'type', 'notes']) form.elements[name].value = device[name];
  $('#form-h').textContent = `Edit ${device.name}`;
  $('#save').textContent = 'Save changes';
  $('#cancel').hidden = false;
  showErrors(form);
  form.elements.name.focus();
}

function resetForm() {
  form.reset();
  form.elements.id.value = '';
  $('#form-h').textContent = 'Add a device';
  $('#save').textContent = 'Add device';
  $('#cancel').hidden = true;
  showErrors(form);
}
$('#cancel').addEventListener('click', resetForm);

form.addEventListener('submit', async (event) => {
  event.preventDefault(); // we send JSON with fetch instead of letting the browser post the form
  const { id, ...device } = Object.fromEntries(new FormData(form));
  device.port = device.port === '' ? undefined : Number(device.port);
  showErrors(form);
  $('#save').disabled = true;
  try {
    if (id) await api.update(Number(id), device);
    else await api.create(device);
    resetForm();
    await poll();
  } catch (err) {
    if (err instanceof ApiError && err.status) showErrors(form, err.fields, err.message);
    else showErrors(form, {}, err.message);
  } finally {
    $('#save').disabled = false;
  }
});

// ---------- theme: follow the system unless the user picked one
const root = document.documentElement;
function applyTheme(theme) {
  if (theme) root.dataset.theme = theme;
  const dark = theme ? theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
  $('#theme').setAttribute('aria-pressed', String(dark));
  $('#theme').textContent = dark ? 'Light theme' : 'Dark theme';
}
let saved = null;
try { saved = localStorage.getItem('theme'); } catch { /* storage blocked: follow the system */ }
applyTheme(saved);
$('#theme').addEventListener('click', () => {
  const next = $('#theme').getAttribute('aria-pressed') === 'true' ? 'light' : 'dark';
  applyTheme(next);
  try { localStorage.setItem('theme', next); } catch { /* not saved, still applied */ }
});

poll();

