import path from 'node:path';
import { openStore } from './store.js';
import { validateDevice } from './validate.js';
import { Monitor } from './monitor.js';
import { devicesToXml, eventsToRss } from './feeds.js';

const PUBLIC = path.join(import.meta.dirname, '..', 'public');
const TYPES = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8' };

class HttpError extends Error {
  constructor(status, message, fields) {
    super(message);
    this.status = status;
    this.fields = fields;
  }
}

function send(res, status, body, type = 'application/json; charset=utf-8', headers = {}) {
  const text = body === null ? '' : typeof body === 'string' ? body : JSON.stringify(body);
  res.writeHead(status, { ...(text ? { 'Content-Type': type, 'Content-Length': Buffer.byteLength(text) } : {}), ...headers });
  res.end(text);
}

async function readJson(req) {
  if (!(req.headers['content-type'] ?? '').startsWith('application/json')) {
    throw new HttpError(415, 'send JSON with Content-Type: application/json');
  }
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 10_240) throw new HttpError(413, 'body too large (10 kB max)');
  }
  try {
    return JSON.parse(text);
  } catch {
    throw new HttpError(400, 'body must be valid JSON');
  }
}

async function serveStatic(res, pathname) {
  const file = path.join(PUBLIC, pathname === '/' ? 'index.html' : decodeURIComponent(pathname));
  if (!file.startsWith(PUBLIC + path.sep)) throw new HttpError(403, 'forbidden');
  try {
    const data = await readFile(file);
    res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] ?? 'application/octet-stream', 'Content-Length': data.length });
    res.end(data);
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'EISDIR') throw new HttpError(404, `not found: ${pathname}`);
    throw err;
  }
}

export async function createApp({ dataFile, timeoutMs = 1500, log = console.log } = {}) {
  const store = await openStore(dataFile);
  const monitor = new Monitor(store, { timeoutMs });
  const events = [];
  let lastEvent = 0;
  const record = (kind, device, text) => {
    events.unshift({ id: ++lastEvent, time: new Date().toISOString(), kind, deviceId: device.id, text });
    events.length = Math.min(events.length, 50);
  };
  monitor.on('change', ({ device, to, result }) =>
    record(to, device, `${device.name} (${device.ip}:${device.port}) is ${to}${result.error ? ` (${result.error})` : ''}`));
  const withStatus = (d) => ({ ...d, status: monitor.result(d.id) });

  function clean(body, exceptId = null) {
    const { device, errors } = validateDevice(body);
    if (errors) throw new HttpError(422, 'validation failed', errors);
    if (store.nameTaken(device.name, exceptId)) throw new HttpError(409, `a device named ${device.name} already exists`, { name: 'this name is taken' });
    return device;
  }
  function find(id) {
    const device = store.get(Number(id));
    if (!device) throw new HttpError(404, `device ${id} not found`);
    return device;
  }

  async function route(req, res, url) {
    const { method } = req;
    const p = url.pathname.replace(/\/+$/, '') || '/';
    const m = p.match(/^\/api\/devices\/(\d+)(\/check)?$/);

    if (p === '/api/devices' && method === 'GET') {
      const type = url.searchParams.get('type'), state = url.searchParams.get('state'), q = url.searchParams.get('q');
      let list = store.list().map(withStatus);
      if (type) list = list.filter((d) => d.type === type);
      if (state) list = list.filter((d) => d.status.state === state);
      if (q) list = list.filter((d) => d.name.toLowerCase().includes(q.toLowerCase()) || d.ip.includes(q));
      return send(res, 200, list, undefined, { 'X-Total-Count': String(list.length) });
    }
    if (p === '/api/devices' && method === 'POST') {
      const device = await store.add(clean(await readJson(req)));
      record('added', device, `${device.name} (${device.ip}) was added`);
      monitor.check(device).catch(console.error);
      return send(res, 201, withStatus(device), undefined, { Location: `/api/devices/${device.id}` });
    }
    if (p === '/api/devices.xml' && method === 'GET') {
      return send(res, 200, devicesToXml(store.list(), (id) => monitor.result(id)), 'application/xml; charset=utf-8');
    }
    if (m && !m[2] && method === 'GET') return send(res, 200, withStatus(find(m[1])));
    if (m && !m[2] && method === 'PUT') {
      const id = find(m[1]).id;
      const device = await store.update(id, clean(await readJson(req), id));
      monitor.forget(id);
      record('updated', device, `${device.name} (${device.ip}:${device.port}) was updated`);
      monitor.check(device).catch(console.error);
      return send(res, 200, withStatus(device));
    }
    if (m && !m[2] && method === 'DELETE') {
      const device = await store.remove(find(m[1]).id);
      monitor.forget(device.id);
      record('removed', device, `${device.name} (${device.ip}) was removed`);
      return send(res, 204, null);
    }
    if (m && m[2] && method === 'POST') {
      const device = find(m[1]);
      const result = await monitor.check(device);
      if (result.state === 'skipped') throw new HttpError(403, `refusing to probe ${device.ip}: not a LAN address`);
      return send(res, 200, { id: device.id, ip: device.ip, port: device.port, ...result });
    }
    if (p === '/api/status' && method === 'GET') {
      const devices = store.list().map((d) => ({ id: d.id, ...monitor.result(d.id) }));
      const count = (s) => devices.filter((d) => d.state === s).length;
      return send(res, 200, { time: new Date().toISOString(), lastSweep: monitor.lastSweep, version: store.version, lastEvent,
        total: devices.length, up: count('up'), down: count('down'), unknown: count('unknown'), devices });
    }
    if (p === '/api/events' && method === 'GET') return send(res, 200, events);
    if (p === '/feed.rss' && method === 'GET') {
      return send(res, 200, eventsToRss(events, `http://${req.headers.host}`), 'application/rss+xml; charset=utf-8');
    }
    if (p === '/api' || p.startsWith('/api/')) throw new HttpError(404, `no route for ${method} ${url.pathname}`); // not '/api.js'!
    if (method === 'GET' || method === 'HEAD') return serveStatic(res, url.pathname);
    throw new HttpError(405, 'method not allowed');
  }

  const server = http.createServer((req, res) => {
    const t0 = performance.now();
    res.on('finish', () => log(`${req.method} ${req.url} ${res.statusCode} ${Math.round(performance.now() - t0)}ms`));
    route(req, res, new URL(req.url, 'http://localhost')).catch((err) => {
      if (!(err instanceof HttpError)) console.error(err);
      if (res.headersSent) return res.destroy();
      const body = err instanceof HttpError ? { error: err.message, ...(err.fields ? { fields: err.fields } : {}) } : { error: 'internal server error' };
      send(res, err.status ?? 500, body);
    });
  });
  return { server, store, monitor, events };
}

